<template>
  <article
    :id="anchorId"
    class="fu-comment"
    :class="{
      'fu-comment--note': variant === 'note',
      'fu-comment--reply': variant === 'reply',
      'is-deleted': item.is_deleted,
    }"
  >
    <FuAvatar v-if="!item.is_deleted" :name="avatarName" :src="item.creator?.avatar" size="sm" />
    <div v-else class="fu-comment__avatar-gap"><Trash2 :size="14" /></div>

    <div class="fu-comment__main">
      <!-- Placeholder for a deleted comment that still has replies -->
      <div v-if="item.is_deleted" class="fu-comment__deleted">This comment was deleted.</div>

      <template v-else>
        <header class="fu-comment__head">
          <span class="fu-comment__name">{{ authorName }}</span>
          <span class="fu-comment__time" :title="fullDate(item.created_at)">{{ whenLabel }}</span>
          <span v-if="item.is_edited" class="fu-comment__edited" :title="`Edited ${fullDate(item.edited_at)}`">
            (edited)
          </span>
          <span
            v-if="item.is_pinned"
            class="fu-comment__pinned"
            :title="item.pinned_by?.name ? `Pinned by ${item.pinned_by.name}` : 'Pinned'"
          >
            <Pin :size="12" /> Pinned
          </span>

          <FusionActionButton
            v-if="actions.length"
            class="fu-comment__more"
            size="sm"
            variant="subtle"
            :icon="Ellipsis"
            :aria-label="`${noun} actions`"
            :aria-expanded="actionsOpen"
            @click="actionsOpen = !actionsOpen"
          />
        </header>

        <div v-if="actionsOpen" class="fu-comment__actions">
          <FusionButton
            v-for="action in actions"
            :key="action.key"
            size="sm"
            :variant="action.key === 'delete' ? 'danger' : 'subtle'"
            :text="action.text"
            @click="run(action.key)"
          />
        </div>

        <div v-if="hasBody" class="fu-comment__bubble" v-html="safeBody" />

        <FuDiscussionAttachments :files="item.attachments || []" />
      </template>

      <!-- Reply + whatever the parent adds (the thread summary) -->
      <div v-if="showReply || $slots.footer" class="fu-comment__footer">
        <button v-if="showReply" type="button" class="fu-comment__reply" @click="emit('reply', item)">
          <Reply :size="14" /> Reply
        </button>
        <slot name="footer" />
      </div>
    </div>
  </article>
</template>

<script setup>
import { computed, ref } from "vue";
import { Ellipsis, Pin, Trash2, Reply } from "@lucide/vue";
import { sanitizeHtml } from "@/utils/sanitizeHtml";
import FuDiscussionAttachments from "./FuDiscussionAttachments.vue";

const props = defineProps({
  /**
   * Note or comment from the API:
   * { id, body, creator, attachments, is_pinned, pinned_by, is_edited, edited_at,
   *   is_deleted, created_at, can: { edit, delete, pin, reply } }
   */
  item: { type: Object, required: true },
  // "note" | "comment" | "reply"
  variant: { type: String, default: "comment" },
});

const emit = defineEmits(["pin", "edit", "delete", "reply"]);

const actionsOpen = ref(false);

const showReply = computed(() => !props.item.is_deleted && !!props.item.can?.reply);

const noun = computed(() => (props.variant === "note" ? "Note" : props.variant === "reply" ? "Reply" : "Comment"));
const anchorId = computed(() => `${props.variant === "note" ? "note" : "comment"}-${props.item.id}`);
const authorName = computed(() => props.item.creator?.name || "Former member");
const avatarName = computed(() => props.item.creator?.full_name || authorName.value);
const safeBody = computed(() => sanitizeHtml(props.item.body || ""));
const hasBody = computed(() => !!(props.item.body_text || "").trim() || /<img/i.test(props.item.body || ""));

const actions = computed(() => {
  const can = props.item.can || {};
  const list = [];
  if (can.pin) list.push({ key: "pin", text: props.item.is_pinned ? "Unpin" : "Pin" });
  if (can.edit) list.push({ key: "edit", text: "Edit" });
  if (can.delete) list.push({ key: "delete", text: "Delete" });
  return list;
});

// "Today, 14:20" · "Yesterday" · "3 days ago" · "12 Oct"
const whenLabel = computed(() => {
  if (!props.item.created_at) return "";
  const date = new Date(props.item.created_at);
  const days = Math.floor((Date.now() - date) / 86400000);

  if (days <= 0 && date.toDateString() === new Date().toDateString()) {
    return `Today, ${date.toLocaleTimeString(undefined, { hour: "2-digit", minute: "2-digit" })}`;
  }
  if (days <= 1) return "Yesterday";
  if (days < 7) return `${days} days ago`;
  return date.toLocaleDateString(undefined, { day: "numeric", month: "short" });
});

function fullDate(value) {
  return value ? new Date(value).toLocaleString(undefined, { dateStyle: "medium", timeStyle: "short" }) : "";
}

function run(action) {
  actionsOpen.value = false;
  emit(action, props.item);
}
</script>

