<template>
  <div class="fc-root">
    <template v-for="(page, pageIndex) in pages" :key="page.id">
      <div
        v-for="field in page.fields || []"
        :key="field.id"
        :ref="(el) => (fieldEls[field.id] = el)"
        class="fc-field"
        :class="{
          'fc-field--mine': isMine(field),
          'fc-field--filled': isFilled(field),
          'fc-field--flash': flashFieldId === field.id,
        }"
        :style="{ ...fieldStyle(field, pageIndex), ...chromeStyle(field) }"
      >
        <template v-if="field.type === 'signature' || field.type === 'initials'">
          <div v-if="resolvedValue(field)" class="fc-field__signed">
            <img
                v-if="resolvedValue(field).dataUrl || resolvedValue(field).url"
                :src="resolvedValue(field).dataUrl || resolvedValue(field).url"
                class="fc-field__sig-img"
                :alt="field.type"
            />
            <span v-else class="fc-field__sig-typed">{{ resolvedValue(field).text }}</span>
            <span class="fc-field__signed-name">{{ signerName(field) }}</span>
          </div>
          <button
            v-else-if="isMine(field)"
            type="button"
            class="fc-field__btn"
            :disabled="readOnly"
            @click="field.type === 'signature' ? openSignature(field) : openInitials(field)"
          >
            <component :is="fieldTypeDef(field.type).icon" :size="13" />
            <span>{{ field.placeholder || (field.type === "signature" ? "Sign here" : "Initial") }}</span>
          </button>
          <div v-else class="fc-field__readonly">
            <component :is="fieldTypeDef(field.type).icon" :size="13" />
            <span class="fc-field__label">{{ fieldTypeDef(field.type).label }}</span>
          </div>
        </template>

        <template v-else-if="field.type === 'date'">
          <DateCaptureField
            v-if="isMine(field)"
            :value="resolvedValue(field) || null"
            :placeholder="field.placeholder"
            :read-only="readOnly"
            @update:value="(v) => setValue(field.id, v)"
          />
          <div v-else-if="resolvedValue(field)" class="fc-field__readonly">{{ formatDate(resolvedValue(field)) }}</div>
          <div v-else class="fc-field__readonly">
            <component :is="fieldTypeDef('date').icon" :size="13" />
            <span class="fc-field__label">{{ fieldTypeDef('date').label }}</span>
          </div>
        </template>

        <template v-else-if="field.type === 'text'">
          <input
            v-if="isMine(field)"
            type="text"
            class="fc-field__input"
            :disabled="readOnly"
            :required="field.required"
            :placeholder="field.placeholder || 'Enter value...'"
            :value="resolvedValue(field) || ''"
            @input="(e) => setValue(field.id, e.target.value)"
          />
          <div v-else-if="resolvedValue(field)" class="fc-field__readonly">{{ resolvedValue(field) }}</div>
          <div v-else class="fc-field__readonly">
            <component :is="fieldTypeDef('text').icon" :size="13" />
            <span class="fc-field__label">{{ fieldTypeDef('text').label }}</span>
          </div>
        </template>

        <template v-else-if="field.type === 'dropdown'">
          <select
            v-if="isMine(field)"
            class="fc-field__input"
            :disabled="readOnly"
            :required="field.required"
            :value="resolvedValue(field) || ''"
            @change="(e) => setValue(field.id, e.target.value)"
          >
            <option value="" disabled>
              {{ field.placeholder || "Select an option" }}
            </option>
            <option v-for="opt in field.options || []" :key="opt" :value="opt">
              {{ opt }}
            </option>
          </select>
          <div v-else-if="resolvedValue(field)" class="fc-field__readonly">{{ resolvedValue(field) }}</div>
          <div v-else class="fc-field__readonly">
            <component :is="fieldTypeDef('dropdown').icon" :size="13" />
            <span class="fc-field__label">{{ fieldTypeDef('dropdown').label }}</span>
          </div>
        </template>

        <template v-else-if="field.type === 'radio'">
          <div v-if="isMine(field)" class="fc-field__radio-list">
            <label
              v-for="opt in field.options || []"
              :key="opt"
              class="fc-field__radio-row"
            >
              <input
                type="radio"
                :name="field.id"
                :disabled="readOnly"
                :checked="resolvedValue(field) === opt"
                @change="setValue(field.id, opt)"
              />
              <span>{{ opt }}</span>
            </label>
          </div>
          <div v-else-if="resolvedValue(field)" class="fc-field__readonly">{{ resolvedValue(field) }}</div>
          <div v-else class="fc-field__readonly">
            <component :is="fieldTypeDef('radio').icon" :size="13" />
            <span class="fc-field__label">{{ fieldTypeDef('radio').label }}</span>
          </div>
        </template>

        <template v-else-if="field.type === 'checkbox'">
          <label v-if="isMine(field)" class="fc-field__checkbox-row">
            <input
              type="checkbox"
              :disabled="readOnly"
              :checked="!!resolvedValue(field)"
              @change="(e) => setValue(field.id, e.target.checked)"
            />
            <span v-if="field.placeholder">{{ field.placeholder }}</span>
          </label>
          <div v-else class="fc-field__readonly fc-field__checkbox-row">
            <Check v-if="resolvedValue(field)" :size="14" />
            <span v-if="field.placeholder">{{ field.placeholder }}</span>
          </div>
        </template>

        <template v-else-if="field.type === 'file'">
          <button
            v-if="isMine(field)"
            type="button"
            class="fc-field__file"
            :disabled="readOnly"
            @click="openFileUpload(field)"
          >
            <component :is="fieldTypeDef('file').icon" :size="13" />
            <span>{{
              resolvedValue(field)?.name || field.placeholder || "Upload file"
            }}</span>
          </button>
          <div v-else class="fc-field__readonly fc-field__file">
            <component :is="fieldTypeDef('file').icon" :size="13" />
            <span>{{ resolvedValue(field)?.name || fieldTypeDef('file').label }}</span>
          </div>
        </template>
      </div>
    </template>

    <SignatureCaptureModal
      :isVisible="signatureModalOpen"
      :signerName="recipient?.name || ''"
      @close="signatureModalOpen = false"
      @signed="onSignatureCaptured"
    />
    <InitialsCaptureModal
      :isVisible="initialsModalOpen"
      :signerName="recipient?.name || ''"
      @close="initialsModalOpen = false"
      @initialed="onInitialsCaptured"
    />
    <FileUploadCaptureModal
      :isVisible="fileModalOpen"
      @close="fileModalOpen = false"
      @uploaded="onFileUploaded"
    />
  </div>
</template>

<script setup>
import { ref, reactive, watch, onBeforeUnmount, nextTick } from "vue";
import { Check } from "@lucide/vue";
import { fieldTypeDef, PAGE_HEIGHT_PX } from "./fieldTypes.js";
import { resolveRecipientColor, bgTint, canRecipientAct } from "./recipientColor.js";
import SignatureCaptureModal from "./SignatureCaptureModal.vue";
import InitialsCaptureModal from "./InitialsCaptureModal.vue";
import DateCaptureField from "./DateCaptureField.vue";
import FileUploadCaptureModal from "./FileUploadCaptureModal.vue";

const props = defineProps({
  pages: { type: Array, default: () => [] },
  recipient: { type: Object, default: null },
  recipients: { type: Array, default: () => [] },
  readOnly: { type: Boolean, default: false },
  hostEl: { type: Object, default: null },
});
const emit = defineEmits(["update:capturedFields"]);

const values = reactive({});
const fieldEls = reactive({});
const flashFieldId = ref(null);

function focusField(fieldId) {
  const el = fieldEls[fieldId];
  if (!el) return;
  el.scrollIntoView({ behavior: "smooth", block: "center" });
  flashFieldId.value = fieldId;
  setTimeout(() => {
    if (flashFieldId.value === fieldId) flashFieldId.value = null;
  }, 1200);
}
defineExpose({ focusField });

watch(
  () => props.recipient,
  (r) => {
    Object.keys(values).forEach((k) => delete values[k]);
    Object.assign(values, r?.field_values || {});
  },
  { immediate: true }
);

watch(
  values,
  () => {
    emit(
      "update:capturedFields",
      Object.entries(values).map(([fieldId, value]) => ({ fieldId, value }))
    );
  },
  { deep: true }
);

function setValue(fieldId, value) {
  values[fieldId] = value;
}
function isFilled(field) {
  const v = resolvedValue(field);
  return v !== undefined && v !== null && v !== "";
}
function isMine(field) {
  return !props.readOnly && isOwnField(field);
}
function isOwnField(field) {
  return field.recipientId === props.recipient?.id && canRecipientAct(props.recipient);
}
function colorFor(recipientId) {
  return resolveRecipientColor(props.recipients, recipientId);
}
function chromeStyle(field) {
  if (isFilled(field)) return { border: "none", background: "transparent", color: "#111827" };
  if (isOwnField(field)) {
    return {
      borderColor: colorFor(field.recipientId),
      backgroundColor: bgTint(colorFor(field.recipientId)),
      color: colorFor(field.recipientId),
    };
  }
  return { borderColor: "#d1d5db", backgroundColor: "#f3f4f6", color: "#9ca3af" };
}
function signerName(field) {
  if (isOwnField(field)) return props.recipient?.name || "";
  return findOwner(field.recipientId)?.name || "";
}

function findOwner(recipientId) {
  return props.recipients.find((r) => String(r.id) === String(recipientId));
}
function resolvedValue(field) {
  if (isOwnField(field)) return values[field.id];
  return findOwner(field.recipientId)?.field_values?.[field.id];
}
function formatDate(value) {
  if (!value) return "";
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) return value;
  return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "numeric" });
}

const pageRects = ref([]);
let ro = null;

function measure() {
  const host = props.hostEl;
  if (!host) return;
  const pageEls = host.querySelectorAll(".page-renderer");
  pageRects.value = props.pages.map((_, i) => {
    const el = pageEls[i];
    if (!el) return null;
    return {
      top: el.offsetTop,
      left: el.offsetLeft,
      width: el.offsetWidth,
      height: el.offsetHeight,
    };
  });
}

watch(
  () => props.hostEl,
  async (el) => {
    ro?.disconnect();
    ro = null;
    if (!el) return;
    await nextTick();
    measure();
    ro = new ResizeObserver(() => measure());
    ro.observe(el);
  },
  { immediate: true }
);
watch(
  () => props.pages,
  async () => {
    await nextTick();
    measure();
  }
);
onBeforeUnmount(() => ro?.disconnect());

function fieldStyle(field, pageIndex) {
  const rect = pageRects.value[pageIndex];
  if (!rect) return { display: "none" };
  return {
    position: "absolute",
    left: rect.left + field.x * rect.width + "px",
    top: rect.top + field.y * rect.height + "px",
    width: field.width * rect.width + "px",
    // Height is stored as a fraction of the editor's nominal page height
    // (PAGE_HEIGHT_PX), not a fraction of the actual rendered page height —
    // matching how FieldOverlay.vue renders it in the editor.
    height: field.height * PAGE_HEIGHT_PX + "px",
  };
}

const signatureModalOpen = ref(false);
const initialsModalOpen = ref(false);
const fileModalOpen = ref(false);
const activeField = ref(null);

function openSignature(field) {
  if (props.readOnly) return;
  activeField.value = field;
  signatureModalOpen.value = true;
}
function openInitials(field) {
  if (props.readOnly) return;
  activeField.value = field;
  initialsModalOpen.value = true;
}
function openFileUpload(field) {
  if (props.readOnly) return;
  activeField.value = field;
  fileModalOpen.value = true;
}
function onSignatureCaptured(payload) {
  if (!activeField.value) return;
  setValue(activeField.value.id, payload);
}
function onInitialsCaptured(payload) {
  if (!activeField.value) return;
  setValue(activeField.value.id, payload);
}
function onFileUploaded(payload) {
  if (!activeField.value) return;
  setValue(activeField.value.id, payload);
}
</script>

