<template>
  <div class="fu-action-btn-wrapper" @mouseenter="showTip" @mouseleave="hideTip" @click="hideTip">
    <button
      class="fu-action-btn"
      :class="[
        `fu-action-btn--${size}`,
        `fu-action-btn--${variant}`,
        { 'is-loading': loading },
      ]"
      :disabled="disabled || loading"
      :aria-label="label"
      @click="!loading ? $emit('click', $event) : null"
    >
      <span v-if="loading" class="fu-spinner"></span>
      <component v-else-if="icon" :is="icon" class="fu-action-btn__icon" :size="20" />
    </button>

    <!-- A count (or a dot) on top of the button's corner. It hides itself when there is nothing to show. -->
    <span
      v-if="badgeShown"
      class="fu-action-btn__badge"
      :class="[`fu-action-btn__badge--${badgeTone}`, { 'fu-action-btn__badge--dot': badge === true }]"
      aria-hidden="true"
    >{{ badgeText }}</span>

    <Teleport to="body">
      <span v-if="tooltip && tipVisible" class="fu-tooltip" :style="tipStyle">{{
        tooltip
      }}</span>
    </Teleport>
  </div>
</template>

<script setup lang="ts">
import { computed, onDeactivated, ref, type Component } from "vue";

interface Props {
  disabled?: boolean;
  size?: "sm" | "md" | "lg";
  variant?: "solid" | "subtle" | "outline" | "ghost" | "danger";
  tooltip?: string | null;
  /** Name for screen readers. Icon-only buttons need one; falls back to the tooltip text. */
  ariaLabel?: string;
  loading?: boolean;
  icon?: Component | null;
  /** A number or text shown on the button's top corner, or `true` for a small dot. Nothing shows for 0, empty, null or false. */
  badge?: number | string | boolean | null;
  badgeTone?: "default" | "danger";
  /** Counts above this show as "99+" */
  badgeMax?: number;
}

const props = withDefaults(defineProps<Props>(), {
  disabled: false,
  size: "md",
  variant: "subtle",
  tooltip: null,
  loading: false,
  icon: null,
  badge: null,
  badgeTone: "default",
  badgeMax: 99,
});

const badgeShown = computed(() => {
  const b = props.badge;
  return b === true || (b !== null && b !== undefined && b !== false && b !== "" && b !== 0);
});
const badgeText = computed(() => {
  const b = props.badge;
  if (b === true) return "";
  return typeof b === "number" && b > props.badgeMax ? `${props.badgeMax}+` : String(b);
});
// Screen readers get the count too: "Recipients, 3"
const label = computed(() => {
  const base = props.ariaLabel || props.tooltip || undefined;
  return base && badgeShown.value && props.badge !== true ? `${base}, ${badgeText.value}` : base;
});

defineEmits<{ (e: "click", ev: MouseEvent): void }>();

const tipVisible = ref(false);
const tipStyle = ref({});

function showTip(e: MouseEvent) {
  const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();
  tipStyle.value = {
    position: "fixed",
    left: `${rect.left + rect.width / 2}px`,
    top: `${rect.top - 8}px`,
    transform: "translateX(-50%) translateY(-100%)",
    zIndex: 99999,
  };
  tipVisible.value = true;
}

function hideTip() {
  tipVisible.value = false;
}

// A button that goes away while hovered (a cached page being hidden, say) never gets its mouseleave
onDeactivated(hideTip);
</script>

<style scoped lang="scss">
@use "./FusionActionButton.scss";
</style>
