<template>
  <Teleport to="body">
    <div
      v-if="isVisible"
      class="fu-onboarding-modal__backdrop"
      :class="`fu-onboarding-modal__backdrop--${backdrop}`"
      @click.self="onBackdrop"
    >
      <div
        ref="dialogRef"
        class="fu-onboarding-modal"
        :class="[
          `fu-onboarding-modal--${size}`,
          `fu-onboarding-modal--panel-${panelPosition}`,
          { 'fu-onboarding-modal--no-panel': !hasPanel },
        ]"
        role="dialog"
        aria-modal="true"
        :aria-labelledby="titleId"
        tabindex="-1"
      >
        <div class="fu-onboarding-modal__close">
          <FusionActionButton
            :icon="X"
            variant="ghost"
            size="sm"
            tooltip="Close"
            aria-label="Close"
            @click="emit('close')"
          />
        </div>

        <!-- Main side: anything you want to put in it -->
        <div class="fu-onboarding-modal__main">
          <header
            v-if="title || description || $slots.header"
            class="fu-onboarding-modal__header"
          >
            <slot name="header">
              <h2 v-if="title" :id="titleId" class="fu-onboarding-modal__title">
                {{ title }}
              </h2>
              <p v-if="description" class="fu-onboarding-modal__description">
                {{ description }}
              </p>
            </slot>
          </header>

          <div class="fu-onboarding-modal__body">
            <slot />
          </div>

          <footer v-if="$slots.footer" class="fu-onboarding-modal__footer">
            <slot name="footer" />
          </footer>
        </div>

        <!-- Panel side: colour, words and a picture -->
        <aside v-if="hasPanel" class="fu-onboarding-modal__panel" :style="panelStyle">
          <slot name="panel-content">
            <img
              v-if="panel?.image && imagePosition === 'top'"
              class="fu-onboarding-modal__image"
              :src="panel.image"
              :alt="panel.imageAlt ?? ''"
              @error="hideBrokenImage"
            />
            <div
              v-if="panel?.eyebrow || panel?.title || panel?.content"
              class="fu-onboarding-modal__panel-text"
            >
              <p
                v-if="panel?.eyebrow"
                class="fu-onboarding-modal__eyebrow"
                :style="eyebrowStyle"
              >
                {{ panel.eyebrow }}
              </p>
              <h3 v-if="panel?.title" class="fu-onboarding-modal__panel-title">
                {{ panel.title }}
              </h3>
              <p v-if="panel?.content" class="fu-onboarding-modal__panel-content">
                {{ panel.content }}
              </p>
            </div>
            <img
              v-if="panel?.image && imagePosition === 'bottom'"
              class="fu-onboarding-modal__image"
              :src="panel.image"
              :alt="panel.imageAlt ?? ''"
              @error="hideBrokenImage"
            />
          </slot>
        </aside>
      </div>
    </div>
  </Teleport>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, ref, useSlots, watch } from "vue";
import { X } from "@lucide/vue";
import FusionActionButton from "../actionButton/FusionActionButton.vue";

export interface OnboardingModalPanel {
  /** Small label above the panel title, e.g. "SIGNALS" */
  eyebrow?: string;
  title?: string;
  content?: string;
  /** Picture address. Where it sits is set by `imagePosition`. */
  image?: string;
  imageAlt?: string;
  /** Panel background, any CSS colour. Defaults to the theme's soft surface. */
  bg?: string;
  /** Panel text colour. Defaults to the theme's text colour. */
  color?: string;
  /** Colour of the small label. Defaults to the text colour. */
  eyebrowColor?: string;
}

const props = withDefaults(
  defineProps<{
    isVisible: boolean;
    /** Heading of the main side. Leave empty to build your own inside the default slot. */
    title?: string;
    description?: string;
    /** The coloured side. Leave out to get a plain, single-column modal. */
    panel?: OnboardingModalPanel | null;
    /** Which side the panel is on */
    panelPosition?: "right" | "left";
    /** Picture above or below the panel's words */
    imagePosition?: "top" | "bottom";
    size?: "md" | "lg";
    /** How the page behind is treated: "focus" (dimmed and blurred, so attention stays on the modal), "glass" (light frosted look) or "plain" (just dark) */
    backdrop?: "focus" | "glass" | "plain";
    closeOnBackdrop?: boolean;
    closeOnEscape?: boolean;
  }>(),
  {
    title: "",
    description: "",
    panel: null,
    panelPosition: "right",
    imagePosition: "bottom",
    size: "lg",
    backdrop: "focus",
    closeOnBackdrop: true,
    closeOnEscape: true,
  }
);

const emit = defineEmits<{
  (e: "close"): void;
}>();

const slots = useSlots();
const titleId = `fu-onboarding-modal-title-${Math.random().toString(36).slice(2, 9)}`;
const dialogRef = ref<HTMLElement | null>(null);
let previouslyFocused: HTMLElement | null = null;

const hasPanel = computed(() => !!props.panel || !!slots["panel-content"]);

const panelStyle = computed(() => ({
  ...(props.panel?.bg ? { background: props.panel.bg } : {}),
  ...(props.panel?.color ? { color: props.panel.color } : {}),
}));
const eyebrowStyle = computed(() =>
  props.panel?.eyebrowColor ? { color: props.panel.eyebrowColor } : {}
);

// A picture that cannot be found is hidden instead of showing a broken-image icon
function hideBrokenImage(e: Event) {
  (e.target as HTMLElement).style.display = "none";
}

function onBackdrop() {
  if (props.closeOnBackdrop) emit("close");
}

function onKeydown(e: KeyboardEvent) {
  if (e.key === "Escape" && props.closeOnEscape) {
    e.stopPropagation();
    emit("close");
    return;
  }
  // Keep Tab inside the dialog
  if (e.key === "Tab" && dialogRef.value) {
    const focusable = dialogRef.value.querySelectorAll<HTMLElement>(
      'a[href], button:not([disabled]), input:not([disabled]), select, textarea, [tabindex]:not([tabindex="-1"])'
    );
    if (!focusable.length) return;
    const first = focusable[0]!;
    const last = focusable[focusable.length - 1]!;
    if (e.shiftKey && document.activeElement === first) {
      e.preventDefault();
      last.focus();
    } else if (!e.shiftKey && document.activeElement === last) {
      e.preventDefault();
      first.focus();
    }
  }
}

watch(
  () => props.isVisible,
  async (open) => {
    if (open) {
      previouslyFocused = document.activeElement as HTMLElement | null;
      document.addEventListener("keydown", onKeydown);
      document.body.style.overflow = "hidden";
      await nextTick();
      dialogRef.value?.focus();
    } else {
      document.removeEventListener("keydown", onKeydown);
      document.body.style.overflow = "";
      previouslyFocused?.focus?.();
    }
  },
  { immediate: true }
);

onBeforeUnmount(() => {
  document.removeEventListener("keydown", onKeydown);
  document.body.style.overflow = "";
});
</script>

