// Small allow-list sanitiser for rich text written in the composer (comments, notes).
// Keeps basic formatting, drops everything else (scripts, styles, event handlers, odd URLs).
// Use it on any HTML you put in v-html. The server should sanitise these bodies too; this is the second layer.

const ALLOWED_TAGS = new Set([
  "p", "br", "b", "strong", "i", "em", "u", "s", "del", "span", "a",
  "ul", "ol", "li", "blockquote", "code", "pre", "img",
]);

const SAFE_HREF = /^(https?:|mailto:|\/(?!\/))/i;

// Inline images: only http(s) or same-site paths. Never data:, blob:, javascript: or //host.
const SAFE_SRC = /^(https?:|\/(?!\/))/i;

// Attributes kept per tag (anything else is removed)
const keepAttr = (tag: string, name: string, value: string): boolean => {
  const v = value.trim();
  switch (tag) {
    case "a":
      return name === "href" && SAFE_HREF.test(v);
    case "span":
      return name === "class" && v === "mention";
    case "img":
      return (name === "src" && SAFE_SRC.test(v)) || name === "alt" || name === "data-file-id";
    default:
      return false;
  }
};

export function sanitizeHtml(html: string | null | undefined): string {
  if (!html) return "";

  const doc = new DOMParser().parseFromString(`<body>${html}</body>`, "text/html");

  const clean = (node: Node): void => {
    for (const child of [...node.childNodes]) {
      if (child.nodeType === Node.TEXT_NODE) continue;

      if (child.nodeType !== Node.ELEMENT_NODE) {
        (child as ChildNode).remove();
        continue;
      }

      const el = child as HTMLElement;
      const tag = el.tagName.toLowerCase();

      // Unknown tag: keep its text, drop the tag (scripts and styles are dropped whole)
      if (!ALLOWED_TAGS.has(tag)) {
        if (["script", "style", "iframe", "object", "embed"].includes(tag)) {
          el.remove();
        } else {
          clean(el);
          el.replaceWith(...el.childNodes);
        }
        continue;
      }

      for (const attr of [...el.attributes]) {
        if (!keepAttr(tag, attr.name, attr.value)) el.removeAttribute(attr.name);
      }

      if (tag === "a") {
        el.setAttribute("target", "_blank");
        el.setAttribute("rel", "noopener noreferrer");
      }

      if (tag === "img") {
        // An image without a safe source is dropped rather than left as a broken box
        if (!el.hasAttribute("src")) {
          el.remove();
          continue;
        }
        el.setAttribute("loading", "lazy");
      }

      clean(el);
    }
  };

  clean(doc.body);
  return doc.body.innerHTML;
}
