<template>
  <Teleport v-if="target && active" :to="target">
    <slot />
  </Teleport>
</template>

<script setup lang="ts">
import { computed, inject, type Ref } from "vue";

/**
 * Puts its content in the pinned footer of the FusionTab it sits in, but only while its own
 * tab is the one being shown. Use it for a bar that belongs to one tab, such as a reply bar.
 *
 *   <FusionTabFooter tab="emails"> … </FusionTabFooter>
 */
const props = defineProps<{
  /** The `key` of the tab this footer belongs to */
  tab: string;
}>();

const tabs = inject<{ activeTab: Ref<string>; footerEl: Ref<HTMLElement | null> } | null>("fuTabs", null);

// The footer area of the tab bar we sit in (empty until it has been drawn)
const target = computed(() => tabs?.footerEl.value ?? null);
const active = computed(() => tabs?.activeTab.value === props.tab);
</script>
