<template>
  <div class="fu-module-menu-wrapper scrollbar__control customScrollBar">
    <ul class="fu-module-menu-wrapper__list">
      <template v-for="(group, groupIndex) in normalizedGroups" :key="groupIndex">
        <li
          v-if="groupIndex > 0 && (group.divider ?? !!group.title)"
          class="fu-module-menu-divider"
          role="separator"
        />
        <li v-if="group.title" class="fu-module-menu-group-title">{{ group.title }}</li>

        <li
          v-for="item in group.items"
          :key="item.path"
          :class="{ active: activePath && activePath.startsWith(item.path) }"
        >
          <router-link class="fu-module-menu-link" :to="item.path">
            <span class="fu-module-menu-link__start">
              <component
                v-if="item.icon"
                :is="item.icon"
                :size="15"
                class="fu-module-menu-icon"
              />
              <span>{{ item.label }}</span>
            </span>

            <FusionBadge
              v-if="item.badge !== undefined && item.badge !== null && item.badge !== ''"
              class="fu-module-menu-badge"
              :text="String(item.badge)"
              size="sm"
              :themeClass="item.badgeTheme || 'fu-badge--danger-subtle'"
            />
          </router-link>
        </li>
      </template>

      <li v-if="isEmpty" class="fu-module-menu-empty">No menu items</li>
    </ul>

    <!-- Custom slot after the list -->
    <slot />
  </div>
</template>

<script setup lang="ts">
import type { Component } from "vue";
import { computed } from "vue";
import FusionBadge from "../badge/FusionBadge.vue";

interface MenuItem {
  label: string;
  path: string;
  icon?: Component;
  /** Count or label shown in a badge at the end of the item (e.g. 2, "4", "99+") */
  badge?: string | number;
  /** FusionBadge themeClass used to colour the badge, e.g. "fu-badge--danger-subtle" | "fu-badge--warning-subtle" */
  badgeTheme?: string;
}

interface MenuGroup {
  /** Optional section label rendered above the group, e.g. "DESK" or "ATTENTION STATES" */
  title?: string;
  /**
   * Show a horizontal rule above this group. Defaults to true when the group has a
   * title (and it isn't the first group) — set to false to show just the label with no rule.
   */
  divider?: boolean;
  items: MenuItem[];
}

const props = defineProps<{
  /** Flat list of menu items — ignored when `groups` is provided */
  items?: MenuItem[];
  /** Sectioned menu items, each with an optional title and divider */
  groups?: MenuGroup[];
  activePath?: string;
}>();

const normalizedGroups = computed<MenuGroup[]>(() => {
  if (props.groups && props.groups.length) return props.groups;
  return [{ items: props.items || [] }];
});

const isEmpty = computed(() =>
  normalizedGroups.value.every((group) => !group.items || !group.items.length)
);
</script>

<style scoped lang="scss">
@import url("./FusionModuleMenu.scss");
</style>
