import { loadGoogleFont } from "./loadGoogleFont";

const FONT_FAMILY_RE = /font-family:\s*([^;'"<,\n]+)/g;

export function preloadDocumentFonts(documentData: any): void {
  if (!documentData) return;

  const qFont = documentData.meta?.theme?.questionFont;
  if (qFont && qFont !== "inherit") loadGoogleFont(qFont.trim());

  for (const page of documentData.pages ?? []) {
    for (const block of page.blocks ?? []) {
      for (const col of block.columns ?? []) {
        for (const widget of col.widgets ?? []) {
          const html = widget.props?.content;
          if (!html) continue;
          for (const [, family] of html.matchAll(FONT_FAMILY_RE)) {
            loadGoogleFont(family.trim().replace(/['"]/g, ""));
          }
        }
      }
    }
  }
}
