<template>
  <nav class="fu-sidebar" :style="sidebarStyle">
    <ul class="fu-sidebar__list">
      <li
        v-for="mod in modules"
        :key="mod.name"
        :class="{
          active: activeModule === mod.name,
          'fu-sidebar__li--flyout-open':
            isCollapsed && hoveredModuleName === mod.name && mod.links?.length,
        }"
        @mouseenter="(e) => onMouseEnter(e, mod.name)"
        @mouseleave="scheduleHide"
      >
        <div
          class="fu-sidebar__item"
          :class="{ 'fu-sidebar__item--collapsed': hideLabels }"
          @click="$emit('select', mod)"
        >
          <div class="fu-sidebar__icon-wrapper">
            <component :is="mod.icon" class="fu-sidebar__icon" :size="20" />
            <span v-if="mod.count" class="fu-sidebar__badge">
              {{ mod.count > 99 ? "99+" : mod.count }}
            </span>
          </div>
          <span v-if="!hideLabels" class="fu-sidebar__label">{{ mod.label }}</span>
        </div>
      </li>
    </ul>

    <Teleport to="body">
      <!-- Per-module flyout when sidebar is collapsed and module has links -->
      <div
        v-if="
          hideLabels &&
          isCollapsed &&
          hoveredModuleName &&
          hoveredModuleData?.links?.length
        "
        class="fu-sidebar__flyout"
        :style="flyoutStyle"
        @mouseenter="cancelHide"
        @mouseleave="scheduleHide"
      >
        <div class="fu-sidebar__flyout-inner">
          <div class="fu-sidebar__flyout-header">
            <component :is="hoveredModuleData.icon" :size="15" />
            <span>{{ hoveredModuleData.label }}</span>
          </div>
          <ul class="fu-sidebar__flyout-links">
            <li
              v-for="link in hoveredModuleData.links"
              :key="link.label"
              class="fu-sidebar__flyout-link"
              @click="onLinkClick(link)"
            >
              <component v-if="link.icon" :is="link.icon" :size="14" />
              <span>{{ link.label }}</span>
            </li>
          </ul>
        </div>
      </div>

      <!-- Simple tooltip when not collapsed (existing behaviour) -->
      <span
        v-else-if="hideLabels && !isCollapsed && hoveredModuleName"
        class="fu-sidebar__tooltip"
        :style="tooltipStyle"
      >
        {{ hoveredModuleData?.label }}
      </span>
    </Teleport>
  </nav>
</template>

<script setup lang="ts">
import { computed, ref, type Component } from "vue";

interface ModuleLink {
  label: string;
  icon?: Component;
  onClick?: () => void;
}

interface Module {
  name: string;
  label: string;
  icon: Component;
  count?: number;
  links?: ModuleLink[];
}

const props = defineProps<{
  modules: Module[];
  activeModule?: string;
  backgroundColor?: string;
  borderRadius?: string;
  hideLabels?: boolean;
  isCollapsed?: boolean;
}>();

const emit = defineEmits(["select"]);

const hoveredModuleName = ref<string | null>(null);
const flyoutStyle = ref<Record<string, string>>({});
const tooltipStyle = ref<Record<string, string>>({});
let hideTimer: ReturnType<typeof setTimeout> | null = null;

const hoveredModuleData = computed(() =>
  props.modules.find((m) => m.name === hoveredModuleName.value) ?? null
);

const sidebarStyle = computed(() => ({
  "--fu-sidebar-bg": props.backgroundColor ?? "var(--fu-brand-background)",
  "--fu-sidebar-radius": props.borderRadius ?? "0px",
  width: props.hideLabels ? "54px" : "70px",
}));

function onMouseEnter(e: MouseEvent, modName: string) {
  if (!props.hideLabels) return;
  cancelHide();
  hoveredModuleName.value = modName;
  const rect = (e.currentTarget as HTMLElement).getBoundingClientRect();


  const iconCenter = rect.top + rect.height / 2;
  flyoutStyle.value = {
    position: "fixed",
    left: `${rect.right + 7}px`,
    top: `${rect.top}px`,
    zIndex: "99999",
    "--arrow-top": `${iconCenter - rect.top}px`,
  };

  // Tooltip: vertically centred (no-links mode)
  tooltipStyle.value = {
    position: "fixed",
    left: `${rect.right + 8}px`,
    top: `${rect.top + rect.height / 2}px`,
    transform: "translateY(-50%)",
    zIndex: "99999",
  };
}

function scheduleHide() {
  hideTimer = setTimeout(() => {
    hoveredModuleName.value = null;
    hideTimer = null;
  }, 120);
}

function cancelHide() {
  if (hideTimer !== null) {
    clearTimeout(hideTimer);
    hideTimer = null;
  }
}

function onLinkClick(link: ModuleLink) {
  hoveredModuleName.value = null;
  link.onClick?.();
}
</script>

<style scoped lang="scss">
