.fu-sidebar__item--collapsed {
  justify-content: center;
}

.fu-sidebar__flyout {
  background: var(--fu-surface-background, #fff);
  border: rem-calc(1) solid var(--fu-border, rgba(0, 0, 0, 0.08));
  border-radius: rem-calc(10);
  box-shadow: 0 rem-calc(8) rem-calc(24) rgba(0, 0, 0, 0.14);
  min-width: rem-calc(200);
  overflow: visible;
  animation: flyout-in 0.15s ease;

  &::before {
    content: "";
    position: absolute;
    right: 100%;
