    border-top: rem-calc(7) solid transparent;
    border-bottom: rem-calc(7) solid transparent;
    border-right: rem-calc(7) solid var(--fu-surface-background, #fff);
    pointer-events: none;
  }
}

@keyframes flyout-in {
  from {
    opacity: 0;
    transform: translateX(rem-calc(-6));
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.fu-sidebar__flyout-inner {
  overflow: hidden;
  border-radius: rem-calc(10);
}

.fu-sidebar__flyout-header {
  display: flex;
  align-items: center;
  gap: rem-calc(8);
  padding: rem-calc(10) rem-calc(14) rem-calc(8);
  font-size: rem-calc(12);
  font-weight: 600;
  color: var(--fu-color-text, #111);
  border-bottom: rem-calc(1) solid var(--fu-border, rgba(0, 0, 0, 0.07));
  opacity: 0.7;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.fu-sidebar__flyout-links {
  margin: 0;
  padding: rem-calc(6) 0;
  list-style: none;
}

.fu-sidebar__flyout-link {
  display: flex;
