<template>
  <span class="fu-spinner" role="status" :aria-label="label">
    <Loader2 :size="pixels" class="fu-spinner__icon" />
  </span>
</template>

<script setup lang="ts">
import { computed } from "vue";
import { Loader2 } from "@lucide/vue";

const props = withDefaults(
  defineProps<{
    size?: "xs" | "sm" | "md" | "lg";
    /** Read out by screen readers */
    label?: string;
  }>(),
  {
    size: "md",
    label: "Loading",
  }
);

const SIZES = { xs: 12, sm: 16, md: 20, lg: 28 };
const pixels = computed(() => SIZES[props.size]);
</script>

