<template>
  <div ref="rootRef" class="fu-view-switcher" @keydown="onKeydown">
    <!-- Trigger: current view's title + count -->
    <button
      ref="triggerRef"
      type="button"
      class="fu-view-switcher__trigger"
      :disabled="disabled"
      aria-haspopup="menu"
      :aria-expanded="open"
      :aria-controls="menuId"
      @click="toggle"
    >
      <component
        :is="active.icon"
        v-if="active?.icon"
        :size="16"
        :stroke-width="2"
        class="fu-view-switcher__trigger-icon"
        :style="active.color ? { color: active.color } : undefined"
      />
      <span class="fu-view-switcher__trigger-label">{{ active?.title ?? active?.label ?? placeholder }}</span>
      <span v-if="showCount(active)" class="fu-view-switcher__count">{{ formatCount(active!.count!) }}</span>
      <ChevronDown :size="16" :stroke-width="2" class="fu-view-switcher__chevron" :class="{ 'is-open': open }" />
    </button>

    <!-- Menu -->
    <Transition name="fu-view-switcher-fade">
      <div
        v-if="open"
        :id="menuId"
        role="menu"
        :aria-label="ariaLabel"
        class="fu-view-switcher__menu"
        :class="`fu-view-switcher__menu--${align}`"
      >
        <div v-if="heading" class="fu-view-switcher__heading">{{ heading }}</div>

        <button
          v-for="(view, i) in views"
          :key="view.key"
          :ref="(el) => (itemRefs[i] = el as HTMLElement | null)"
          type="button"
          role="menuitemradio"
          :aria-checked="view.key === modelValue"
          class="fu-view-switcher__item"
          :class="{ 'is-active': view.key === modelValue }"
          :disabled="view.disabled"
          @click="select(view)"
        >
          <span class="fu-view-switcher__item-icon">
            <component
              :is="view.icon"
              v-if="view.icon"
              :size="16"
              :stroke-width="2"
              :style="view.color ? { color: view.color } : undefined"
            />
          </span>
          <span class="fu-view-switcher__item-text">
            <span class="fu-view-switcher__item-label">{{ view.label }}</span>
            <span v-if="view.description" class="fu-view-switcher__item-desc">{{ view.description }}</span>
          </span>
          <span v-if="showCount(view)" class="fu-view-switcher__item-count">{{ formatCount(view.count!) }}</span>
          <Check v-if="view.key === modelValue" :size="16" :stroke-width="2" class="fu-view-switcher__check" />
          <span v-else class="fu-view-switcher__check-placeholder" />
        </button>

        <!-- Room for saved views / "Save current view" -->
        <template v-if="$slots.footer">
          <div class="fu-view-switcher__divider" />
          <slot name="footer" :close="close" />
        </template>
      </div>
    </Transition>
  </div>
</template>

<script setup lang="ts">
import type { Component } from "vue";
import { computed, nextTick, onBeforeUnmount, ref, watch } from "vue";
import { Check, ChevronDown } from "@lucide/vue";

export interface FuView {
  /** Unique key, this is what `v-model` holds */
  key: string;
  /** Menu label */
  label: string;
  /** Trigger label, falls back to `label` */
  title?: string;
  /** Lucide icon component */
  icon?: Component;
  /** Icon colour, any CSS colour */
  color?: string;
  /** Hidden when null/undefined */
  count?: number | null;
  /** Muted second line in the menu */
  description?: string;
  disabled?: boolean;
}

const props = withDefaults(
  defineProps<{
    views: FuView[];
    modelValue?: string | null;
    disabled?: boolean;
    align?: "left" | "right";
    heading?: string;
    placeholder?: string;
    ariaLabel?: string;
    /** Hide the count when it is 0 */
    hideZeroCounts?: boolean;
  }>(),
  {
    modelValue: null,
    disabled: false,
    align: "left",
    heading: "Views",
    placeholder: "Select view",
    ariaLabel: "List views",
    hideZeroCounts: false,
  }
);

const emit = defineEmits<{
  (e: "update:modelValue", key: string): void;
  (e: "change", view: FuView): void;
}>();

defineSlots<{
  /** Extra menu items under a divider, e.g. saved views */
  footer?(props: { close: () => void }): any;
}>();

const open = ref(false);
const rootRef = ref<HTMLElement | null>(null);
const triggerRef = ref<HTMLElement | null>(null);
const itemRefs = ref<(HTMLElement | null)[]>([]);
const menuId = `fu-view-switcher-${Math.random().toString(36).slice(2, 9)}`;

const active = computed(() => props.views.find((v) => v.key === props.modelValue) ?? null);

function showCount(view: FuView | null) {
  if (!view || view.count == null) return false;
  return !(props.hideZeroCounts && view.count === 0);
}

function formatCount(n: number) {
  return Number(n).toLocaleString();
}

function toggle() {
  open.value ? close() : openMenu();
}

async function openMenu(focusIndex: number | null = null) {
  if (props.disabled) return;
  open.value = true;
  await nextTick();
  const index = focusIndex ?? Math.max(0, props.views.findIndex((v) => v.key === props.modelValue));
  itemRefs.value[index]?.focus();
}

function close({ focusTrigger = false } = {}) {
  open.value = false;
  if (focusTrigger) triggerRef.value?.focus();
}

function select(view: FuView) {
  if (view.disabled) return;
  close({ focusTrigger: true });
  if (view.key !== props.modelValue) {
    emit("update:modelValue", view.key);
    emit("change", view);
  }
}

function onDocumentPointerDown(event: Event) {
  if (rootRef.value && !rootRef.value.contains(event.target as Node)) close();
}

watch(open, (isOpen) => {
  if (isOpen) document.addEventListener("pointerdown", onDocumentPointerDown);
  else document.removeEventListener("pointerdown", onDocumentPointerDown);
});

onBeforeUnmount(() => document.removeEventListener("pointerdown", onDocumentPointerDown));

function focusedIndex() {
  return itemRefs.value.findIndex((el) => el === document.activeElement);
}

function moveFocus(delta: number) {
  const n = props.views.length;
  if (!n) return;
  let i = focusedIndex();
  for (let step = 0; step < n; step++) {
    i = (i + delta + n) % n;
    if (!props.views[i]?.disabled) break;
  }
  itemRefs.value[i]?.focus();
}

function onKeydown(event: KeyboardEvent) {
  if (!open.value) {
    if (event.target === triggerRef.value && ["ArrowDown", "ArrowUp"].includes(event.key)) {
      event.preventDefault();
      openMenu(event.key === "ArrowUp" ? props.views.length - 1 : null);
    }
    return;
  }

  switch (event.key) {
    case "Escape":
      event.preventDefault();
      close({ focusTrigger: true });
      break;
    case "ArrowDown":
      event.preventDefault();
      moveFocus(1);
      break;
    case "ArrowUp":
      event.preventDefault();
      moveFocus(-1);
      break;
    case "Home":
      event.preventDefault();
      itemRefs.value[0]?.focus();
      break;
    case "End":
      event.preventDefault();
      itemRefs.value[props.views.length - 1]?.focus();
      break;
    case "Tab":
      close();
      break;
  }
}

defineExpose({ open: openMenu, close });
</script>

