<template>
  <div v-if="files.length" class="fu-attachments">
    <a
        v-for="file in images"
        :key="file.id"
        class="fu-attachments__image"
        :href="file.url"
        target="_blank"
        rel="noopener"
        :title="file.name"
    >
      <img :src="file.url" :alt="file.name" loading="lazy" />
    </a>

    <a
        v-for="file in others"
        :key="file.id"
        class="fu-attachments__file"
        :href="file.download_url || file.url"
        :title="`Download ${file.name}`"
    >
      <FileIcon :size="16" class="fu-attachments__icon" />
      <span class="fu-attachments__name">{{ file.name }}</span>
      <span class="fu-attachments__size">{{ formatSize(file.size) }}</span>
      <Download :size="14" class="fu-attachments__download" />
    </a>
  </div>
</template>

<script setup>
import { computed } from "vue";
import { File as FileIcon, Download } from "@lucide/vue";

const props = defineProps({
  // [{ id, name, size, is_image, url, download_url }]
  files: { type: Array, default: () => [] },
});

const images = computed(() => props.files.filter((f) => f.is_image));
const others = computed(() => props.files.filter((f) => !f.is_image));

function formatSize(bytes) {
  if (!bytes && bytes !== 0) return "";
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}
</script>

