<template>
  <div
    class="fu-integration-row"
    :class="[`fu-integration-row--${status}`]"
    role="listitem"
  >
    <span class="fu-integration-row__tile" aria-hidden="true">
      <img v-if="image" class="fu-integration-row__image" :src="image" alt="" />
      <component :is="icon" v-else-if="icon" :size="20" />
      <Plug v-else :size="20" />
    </span>

    <span class="fu-integration-row__text">
      <span class="fu-integration-row__name">{{ name }}</span>
      <span v-if="description" class="fu-integration-row__description">{{ description }}</span>
    </span>

    <span class="fu-integration-row__action">
      <slot name="action" :status="status">
        <span v-if="status === 'connected'" class="fu-integration-row__connected">
          <Check :size="16" aria-hidden="true" />
          {{ connectedLabel }}
        </span>

        <span v-else-if="status === 'coming-soon'" class="fu-integration-row__tag">
          {{ comingSoonLabel }}
        </span>

        <FusionButton
          v-else
          variant="outline"
          size="md"
          :text="connectLabel"
          :loading="loading"
          :disabled="disabled"
          :aria-label="`${connectLabel} ${name}`"
          @click="emit('connect')"
        />
      </slot>
    </span>
  </div>
</template>

<script setup lang="ts">
import type { Component } from "vue";
import { Check, Plug } from "@lucide/vue";
import FusionButton from "../button/FusionButton.vue";

withDefaults(
  defineProps<{
    name: string;
    /** The small grey line under the name, e.g. "Email and replies" */
    description?: string;
    /** Logo or picture for the tile. If both `image` and `icon` are missing, a plug icon is shown. */
    image?: string;
    /** A Lucide icon to use in the tile when there is no image */
    icon?: Component | null;
    /**
     * - `available`: shows the Connect button
     * - `connected`: shows the green "Connected" flag and a green tile
     * - `coming-soon`: greys the row out and shows the "Coming soon" tag
     */
    status?: "available" | "connected" | "coming-soon";
    connectLabel?: string;
    connectedLabel?: string;
    comingSoonLabel?: string;
    /** Spinner on the Connect button, while the connection is being set up */
    loading?: boolean;
    disabled?: boolean;
  }>(),
  {
    description: "",
    image: "",
    icon: null,
    status: "available",
    connectLabel: "Connect",
    connectedLabel: "Connected",
    comingSoonLabel: "Coming soon",
    loading: false,
    disabled: false,
  }
);

const emit = defineEmits<{
  (e: "connect"): void;
}>();
</script>

